 75	
 76	function buildPipelineTrack(overviewEntry) {
 77	  if (!overviewEntry || !overviewEntry.pipeline_stages || !overviewEntry.pipeline_stages.length) {
 78	    return '—';
 79	  }
 80	  var badges = overviewEntry.pipeline_stages.map(function (stage) {
 81	    var abbrev = STAGE_ABBREV[stage.type] || stage.type.slice(0, 3).toUpperCase();
 82	    var statusClass = 'stage-pending';
 83	    if (stage.status === 'in-progress') statusClass = 'stage-in-progress';
 84	    else if (stage.status === 'pass')        statusClass = 'stage-pass';
 85	    else if (stage.status === 'fail')        statusClass = 'stage-fail';
 86	    var tooltip = escapeHtml(stage.type) + ' — ' + escapeHtml(stage.agent);
 87	    if (stage.rework_count > 0) tooltip += ' (rework: ' + stage.rework_count + ')';
 88	    var reworkBadge = stage.rework_count > 0
 89	      ? '<span class="rework-indicator" title="Rework count: ' + stage.rework_count + '">' + stage.rework_count + '</span>'
 90	      : '';
 91	    return '<span class="stage-badge ' + statusClass + '" title="' + tooltip + '">' +
 92	      escapeHtml(abbrev) +
 93	      reworkBadge +
 94	    '</span>';
 95	  }).join('');
 96	  return '<div class="pipeline-track">' + badges + '</div>';
 97	}
 98	
 99	function buildRunBadges(item, isActive) {
100	  var badges = '';
101	  if (isActive) {
102	    badges += '<span class="badge badge-in-progress">Running</span>';
103	  }
104	  if (item && item.is_dry_run) {
105	    badges += '<span class="badge badge-dry-run">Dry Run</span>';
106	  }
107	  return badges;
108	}
