146	        '<td>' + statusBadge(wp.status) + '</td>' +
147	      '</tr>';
148	    }).join('');
149	
150	    // Sort project comments newest-first
151	    var comments = (project.project_comments || []).slice().sort(function (a, b) {
152	      return (b.timestamp || '').localeCompare(a.timestamp || '');
153	    });
154	
155	    var commentCards = comments.length
156	      ? comments.map(function (c) {
157	          var priorityClass = c.priority ? ' priority-' + c.priority : '';
158	          var contextHtml = '';
159	          if (c.context && typeof c.context === 'object') {
160	            var ctxItems = Object.entries(c.context).map(function (pair) {
161	              return '<span><strong>' + escapeHtml(pair[0]) + ':</strong> ' + escapeHtml(String(pair[1])) + '</span>';
162	            }).join('<br>');
163	            contextHtml =
164	              '<div style="margin-top:8px;padding:8px 10px;background:var(--color-bg);border-radius:var(--radius);font-size:12px;line-height:1.6">' +
165	                ctxItems +
166	              '</div>';
