  8	function renderProjectList(app) {
  9	  showLoading(app);
 10	
 11	  var SORT_KEY_STORAGE = 'mcp-sort-key';
 12	  var SORT_DIR_STORAGE = 'mcp-sort-dir';
 13	  var PAGE_LIMIT_STORAGE = 'mcp-page-limit';
 14	  var STATUS_STORAGE = 'mcp-status-filter';
 15	  var RUNNER_STORAGE = 'mcp-runner-filter';
 16	
 17	  // --- Pagination / filter state (localStorage-persisted where noted) ---
 18	  var currentPage = 1;
 19	  var pageLimit = (function () {
 20	    var v = parseInt(localStorage.getItem(PAGE_LIMIT_STORAGE), 10);
 21	    return (!isNaN(v) && (v === 25 || v === 50 || v === 100)) ? v : 50;
 22	  }());
 23	  var currentStatus = localStorage.getItem(STATUS_STORAGE) || 'ACTIVE';
 24	  var currentRunner = localStorage.getItem(RUNNER_STORAGE) || '';
 25	  var currentSearch = '';
 26	  var currentSort = localStorage.getItem(SORT_KEY_STORAGE) || 'last_updated';
 27	  var currentDir = localStorage.getItem(SORT_DIR_STORAGE) || 'desc';
 28	
 29	  var lastTotalPages = 1;
 30	  var searchDebounceTimer = null;
 31	
 32	  // ── Action menu (kebab dropdown) state ──
 33	  var openMenuWrapper = null;
 34	
 35	  // Create or reuse the shared menu portal (appended once to <body>)
 36	  var menuPortal = (function () {
 37	    var el = document.getElementById('action-menu-portal');
 38	    if (!el) {
 39	      el = document.createElement('div');
 40	      el.id = 'action-menu-portal';
 41	      el.className = 'action-menu';
 42	      el.setAttribute('role', 'menu');
 43	      document.body.appendChild(el);
 44	    }
 45	    return el;
 46	  }());
 47	
 48	  function closeOpenMenu() {
 49	    menuPortal.style.display = 'none';
 50	    menuPortal.innerHTML = '';
 51	    if (openMenuWrapper) {
 52	      var trigger = openMenuWrapper.querySelector('.action-menu-btn');
 53	      if (trigger) trigger.setAttribute('aria-expanded', 'false');
 54	      openMenuWrapper = null;
 55	    }
 56	  }
 57	
 58	  // ── Runner display helpers ──
 59	
 60	  var RUNNER_LABELS = {
 61	    'vscode':       'VS Code',
 62	    'claude-code':  'Claude Code',
 63	    'orchestrator': 'Orchestrator',
 64	    'unknown':      'Unknown',
 65	  };
 66	
 67	  function runnerLabel(runner) {
 68	    return RUNNER_LABELS[runner] || (runner ? runner : '—');
 69	  }
 70	
 71	  function runnerBadge(runner) {
 72	    var safeRunner = runner && runner !== 'unknown' ? runner : 'unknown';
 73	    var label = RUNNER_LABELS[safeRunner] || (runner ? runner : 'Unknown');
 74	    return '<span class="badge badge-runner badge-runner-' + escapeHtml(safeRunner) + '">' + escapeHtml(label) + '</span>';
 75	  }
 76	
 77	  // ── Build runner filter dropdown options ──
 78	  // Only includes runner values that have at least one project (from runner_counts).
 79	  // Preserves a canonical display order; runners not in runner_counts are omitted.
 80	  // If currentRunner is set to a value absent from runner_counts (stale state),
 81	  // it is included as a zero-count entry so the user can see and clear it.
 82	
 83	  function buildRunnerOptions(runnerCounts) {
 84	    var counts = runnerCounts || {};
 85	
 86	    // Canonical ordering for display (determines option order in dropdown)
 87	    var RUNNER_ORDER = ['orchestrator', 'vscode', 'claude-code', 'unknown'];
 88	
 89	    // Collect runner values that have at least one project, in canonical order
 90	    var activeRunners = RUNNER_ORDER.filter(function (r) {
 91	      return counts[r] !== undefined && counts[r] > 0;
 92	    });
 93	
 94	    // Also include any non-canonical runner values that have projects
 95	    Object.keys(counts).forEach(function (r) {
 96	      if (counts[r] > 0 && RUNNER_ORDER.indexOf(r) === -1) {
 97	        activeRunners.push(r);
 98	      }
 99	    });
100	
101	    // If the current selection is stale (no longer in runner_counts), keep it
102	    // visible so the user can see and clear the filter, even with zero count.
103	    if (currentRunner && counts[currentRunner] === undefined) {
104	      activeRunners.push(currentRunner);
105	    }
106	
107	    // Build <option> elements: "All" first, then one per active runner
108	    var allSel = currentRunner === '' ? ' selected' : '';
109	    var html = '<option value=""' + allSel + '>All</option>';
110	
111	    activeRunners.forEach(function (r) {
112	      var label = RUNNER_LABELS[r] || r;
113	      var cnt = counts[r] !== undefined ? ' (' + counts[r] + ')' : '';
114	      var sel = r === currentRunner ? ' selected' : '';
115	      html += '<option value="' + escapeHtml(r) + '"' + sel + '>' + escapeHtml(label + cnt) + '</option>';
116	    });
117	
118	    return html;
119	  }
120	
121	  // ── Build table HTML (projects already sorted/filtered server-side) ──
122	
123	  function buildTable(projects) {
124	    if (!projects.length) {
125	      return '<p class="text-muted mt-16">No projects found.</p>';
126	    }
127	
128	    function thSort(label, key) {
